    public function testListen()
    {
        $this->assertNotEmpty($this->object->listen('tests/config.json'));
        $_SERVER['REMOTE_HOST'] = __FILE__;
        $this->assertEmpty($this->object->listen(__FILE__));
    }

    /**
     * @covers AdminZone\HookReciever::takeApiChanges
     */
    public function testTakeApiChanges()
    {
        $fakeJson = $this->getTestApiChangeJson(time());
        $this->object->takeApiChanges(\json_decode($fakeJson, true));
        $this->assertEquals(12, count($this->object->changes));
    }

    /**
     * @covers AdminZone\HookReciever::processChanges
     * @depends testTakeApiChanges
     */
    public function testProcessAbraFlexiChanges()
    {
        $this->object->takeApiChanges(\json_decode($this->getTestApiChangeJson($this->object->getLastProcessedVersion()),
                true));
        $this->object->debug = true;
        $this->assertEquals(array_combine(array_keys($this->object->changes),
                array_keys($this->object->changes)),
            $this->object->processAbraFlexiChanges($this->object->changes));
        $this->object->debug = false;
    }

    /**
     * @covers AdminZone\HookReciever::lock
     */
    public function testLock()
    {
        $this->object->unlock();
        $this->object->lock();
        $this->assertFileExists(sys_get_temp_dir().'/webhook.lock');
    }

    /**
