        $this->object->lock();
        $this->assertGreaterThan(0, $this->object->locked());
        $this->object->unlock();
    }

    /**
     * @covers AdminZone\HookReciever::unlock
     */
    public function testUnlock()
    {
        $this->object->lock();
        $this->object->unlock();
        $this->assertFileNotExists(sys_get_temp_dir().'/webhook.lock');
    }

