    /**
     * Main test for Save Webhook to file cache ability
     * 
     * @covers AdminZone\HookReciever::saveWebhookData
     */
    public function testSaveWebhookData()
    {
        $fakeJson       = $this->getTestApiChangeJson($this->object->getGlobalVersion());
        $this->object->takeApiChanges(\json_decode($fakeJson, true));
        $lastInsertedId = $this->object->saveWebhookData($this->object->changes);
        $this->assertEquals($lastInsertedId, $this->object->getLastCachedVersion(), 'webhook test data not cached');
    }

    public function testOnlyFreshHooks()
    {
        $currentTop = $this->object->getLastProcessedVersion();
        $fakeJson   = $this->getTestApiChangeJson($currentTop);
        $this->object->takeApiChanges(\json_decode($fakeJson, true));
        $this->object->saveLastProcessedVersion($currentTop + 3);
        $this->assertEquals(8,
            count($this->object->onlyFreshHooks($this->object->changes)));
    }

    /**
     * @covers AdminZone\HookReciever::wipeCacheRecord
     */
    public function testWipeCacheRecord()
    {
        $jsonData['@in-version']  = 1;
        $jsonData['id']           = 1;
        $jsonData['@evidence']    = 'test';
        $jsonData['@operation']   = 'test';
        $jsonData['external-ids'] = '';
        $this->object->saveWebhookData([$jsonData]);

        $this->object->wipeCacheRecord($jsonData['@in-version']);
        $this->assertTrue($this->object->wipeCacheRecord(1));
        $this->assertNotEquals(1, $this->object->getLastCachedVersion());
    }
